<?php
require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/services/AIJobService.php';
\Services\FeatureManager::requireAction('MOD_AI_ASSISTANCE','view');
$svc=new \Services\AIJobService();$db=$svc->getConnection();$owner=(int)$_SESSION['userid'];$error=$message='';$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$subject=(int)($_GET['sub_id']??$_POST['sub_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){try{
    if(isset($_POST['save_consent'])){$svc->consent($_POST['task'],isset($_POST['enabled']));$message='Preference saved.';}
    elseif(isset($_POST['queue'])){$job=$svc->queueSubject($subject,(int)$_POST['provider_id'],$_POST['task'],isset($_POST['reviewed']));$message='Draft job '.$job.' is recorded. Its current status appears below.';}
    elseif(isset($_POST['retry'])){$svc->retry((int)$_POST['job_id']);$message='Retry queued with a short delay.';}
    elseif(isset($_POST['review'])){$svc->review((int)$_POST['job_id'],$_POST['decision']==='approve',$_POST['remarks']??'');$message='Review recorded. Academic records remain controlled by their existing workflows.';}
}catch(Throwable $ex){$error=$ex->getMessage();}}
$stmt=$db->prepare('SELECT task_key,is_enabled FROM ai_job_consents WHERE user_id=?');$stmt->bind_param('i',$owner);$stmt->execute();$consents=array_column($stmt->get_result()->fetch_all(MYSQLI_ASSOC),'is_enabled','task_key');
$source=null;if($subject){try{$svc->assertSubjectScope($subject);require_once __DIR__.'/seeassessment.class.php';$source=(new SEEAssessment())->calculateSEECOAttainment($subject);}catch(Throwable $ex){$error=$ex->getMessage();}}
$page_title='Optional AI drafts';require __DIR__.'/header.php';
?>
<div class="container my-4"><h4>Optional AI drafts</h4><p>Generate an analysis or proposed action plan from reviewed attainment summaries. Individual names, roll numbers and question marks are excluded. Suggestions require human review; a proposed action is not a completed ATR.</p>
