<div class="row g-3 mb-4"><?php foreach(\Services\AIJobService::TASKS as $task):?><div class="col-md-6"><form method="post" class="card card-body"><input type="hidden" name="task" value="<?= $task ?>"><label><input type="checkbox" name="enabled" <?= !empty($consents[$task])?'checked':'' ?>> Opt in: <?= $e(str_replace('_',' ',strtolower($task))) ?></label><button class="btn btn-outline-primary btn-sm mt-2" name="save_consent">Save preference</button></form></div><?php endforeach ?></div>
<?php require_once __DIR__.'/core/SubjectCatalog.php';$courses=\College\SubjectCatalog::visible($db,$_SESSION); ?>
<form method="get" class="d-flex gap-2 mb-3"><label class="align-self-center">Course</label><select class="form-select" name="sub_id" required><option value="">Choose course</option><?php foreach($courses as $c):?><option value="<?= (int)$c['id'] ?>" <?= $subject===(int)$c['id']?'selected':'' ?>><?= $e($c['subcode'].' — '.$c['sub_fullname'].' — '.$c['class_name']) ?></option><?php endforeach ?></select><button class="btn btn-secondary">Review source</button></form>
<?php if(!empty($source['status'])):?><div class="table-responsive"><table class="table table-sm"><thead><tr><th>CO</th><th>Attained / evaluated</th><th>Missing</th><th>Measured</th><th>Estimated</th><th>Cohort %</th><th>Evidence</th></tr></thead><tbody><?php foreach($source['data'] as $num=>$r):?><tr><td>CO<?= (int)$num ?></td><td><?= (int)$r['attained_students'] ?> / <?= (int)$r['evaluated_students'] ?></td><td><?= (int)$r['missing_students'] ?></td><td><?= (int)$r['measured_students'] ?></td><td><?= (int)$r['estimated_students'] ?></td><td><?= $e($r['cohort_percentage']??'Unavailable') ?></td><td><?= $e($r['basis']) ?></td></tr><?php endforeach ?></tbody></table></div>
<form method="post" class="card card-body"><input type="hidden" name="sub_id" value="<?= $subject ?>"><label>Task</label><select class="form-select mb-2" name="task"><?php foreach(\Services\AIJobService::TASKS as $task):?><option><?= $task ?></option><?php endforeach ?></select><label>Provider</label><select class="form-select mb-2" name="provider_id" required><option value="">Choose provider</option><?php foreach($db->query('SELECT id,name,kind FROM ai_providers WHERE is_enabled=1 ORDER BY id')->fetch_all(MYSQLI_ASSOC) as $p):?><option value="<?= (int)$p['id'] ?>"><?= $e($p['name'].' — '.$p['kind']) ?></option><?php endforeach ?></select><label><input type="checkbox" name="reviewed" required> I reviewed the metrics and approve sending this summary to the selected provider.</label><button class="btn btn-primary mt-2" name="queue">Queue draft</button></form><?php elseif($source):?><div class="alert alert-info"><?= $e($source['err']??'Evidence unavailable') ?></div><?php endif ?>
