$stmt=$db->prepare('SELECT j.*,s.subject_id,s.cutoff_at FROM ai_jobs j JOIN report_snapshots s ON s.id=j.snapshot_id WHERE j.owner_user_id=? ORDER BY j.id DESC LIMIT 30');$stmt->bind_param('i',$owner);$stmt->execute();$jobs=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
if(in_array($_SESSION['role'],['hod','admin','academic_section','superadmin'],true)){if($_SESSION['role']==='hod'){$stmt=$db->prepare("SELECT j.*,s.subject_id,s.cutoff_at FROM ai_jobs j JOIN report_snapshots s ON s.id=j.snapshot_id JOIN subjects su ON su.id=s.subject_id JOIN classes c ON c.id=su.class_id JOIN specialization sp ON sp.id=c.spec_id JOIN departments d ON d.id=sp.dept_id WHERE d.username=? AND j.status IN ('DRAFT','APPROVED') ORDER BY j.id DESC LIMIT 30");$stmt->bind_param('s',$_SESSION['user']);$stmt->execute();$jobs=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);}else{$jobs=$db->query("SELECT j.*,s.subject_id,s.cutoff_at FROM ai_jobs j JOIN report_snapshots s ON s.id=j.snapshot_id WHERE j.status IN ('DRAFT','APPROVED') ORDER BY j.id DESC LIMIT 30")->fetch_all(MYSQLI_ASSOC);}}
// Department reviewers can open a draft by its ID; scope is checked before any output is rendered.
if(isset($_GET['job_id'])&&in_array($_SESSION['role'],['hod','admin','academic_section','superadmin'],true)){$jid=(int)$_GET['job_id'];$stmt=$db->prepare('SELECT j.*,s.subject_id,s.cutoff_at FROM ai_jobs j JOIN report_snapshots s ON s.id=j.snapshot_id WHERE j.id=?');$stmt->bind_param('i',$jid);$stmt->execute();$job=$stmt->get_result()->fetch_assoc();if($job){try{$svc->assertSubjectScope((int)$job['subject_id']);$jobs=[$job];}catch(Throwable $ex){$jobs=[];echo '<p>'.$e($ex->getMessage()).'</p>';}}}
foreach($jobs as $j):try{$svc->assertSubjectScope((int)$j['subject_id']);}catch(Throwable $ex){continue;}?><div class="card card-body my-3"><strong>Draft <?= (int)$j['id'] ?> — <?= $e($j['status']) ?></strong><small>Course <?= (int)$j['subject_id'] ?> · Evidence as of <?= $e($j['cutoff_at']) ?> · <?= $e($j['model_id']??'Pending provider') ?></small>
<?php if($j['error_message']):?><p><?= $e($j['error_message']) ?></p><?php endif ?><?php $output=json_decode($j['output_json']??'null',true);foreach(['observations'=>'Observations','suggestions'=>'Proposed actions'] as $key=>$title):?><?php if(!empty($output[$key])):?><h6 class="mt-2"><?= $title ?></h6><ul><?php foreach($output[$key] as $item):?><li><?= $e($item['text']) ?> <small>(<?= $e(implode(', ',$item['evidence_ids'])) ?>)</small></li><?php endforeach ?></ul><?php endif ?><?php endforeach ?>
<?php if($j['status']==='FAILED'&&(int)$j['attempts']<3&&(int)$j['owner_user_id']===$owner):?><form method="post"><input type="hidden" name="job_id" value="<?= (int)$j['id'] ?>"><button class="btn btn-outline-secondary btn-sm" name="retry">Retry</button></form><?php endif ?>
<?php if($j['status']==='DRAFT'&&in_array($_SESSION['role'],['hod','admin','academic_section','superadmin'],true)&&\Services\FeatureManager::canAction('MOD_AI_ASSISTANCE','approve')):?><form method="post"><input type="hidden" name="job_id" value="<?= (int)$j['id'] ?>"><label>Review remarks</label><textarea class="form-control mb-2" name="remarks" required></textarea><select name="decision" class="form-select mb-2"><option value="approve">Approve draft</option><option value="reject">Reject draft</option></select><button class="btn btn-outline-success btn-sm" name="review">Record review</button></form><?php endif ?></div><?php endforeach ?></div>
